                  <SidebarMenuButton isActive={settingsActive} onClick={onSettingsClick}>
                    <Settings2 />
                    <span>Settings</span>
                  </SidebarMenuButton>
                </SidebarMenuItem>
              </SidebarMenu>
            </SidebarGroupContent>
          </SidebarGroup>
        </SidebarContent>
      </Sidebar>
    </SidebarProvider>
  )
}
import type { MouseEvent as ReactMouseEvent, RefObject } from "react";
import { SortableContext, verticalListSortingStrategy } from "@dnd-kit/sortable";

import { NoteRow } from "@/features/notes/list/components/note-row";
import { SettingsMiddlePane } from "@/features/settings/components/desktop/settings-panel";
import type { SettingsSectionId } from "@/features/settings/lib/sections";

import { focusNoScroll } from "@/shared/lib/dom";
import type { AppMode } from "@typenotes/shared/types";

type DesktopMiddlePaneProps = {
  appMode: AppMode;
  activeSettingsSection: SettingsSectionId;
  onSettingsSectionChange: (id: SettingsSectionId) => void;
  notesPanelRef: RefObject<HTMLDivElement | null>;
  middlePaneRef: RefObject<HTMLDivElement | null>;
  lastLeftPaneFocusRef: RefObject<string>;
  notesTitle: string;
  notes: Array<{ path: string; name: string }>;
  notePreviews: Record<string, import("@typenotes/shared/format").NotePreview>;
  selectedNotes: Set<string>;
  onNotesKeyDown: (event: React.KeyboardEvent<HTMLDivElement>) => void;
  onNoteClick: (notePath: string, event: ReactMouseEvent, parentPath?: string) => void;
  onNoteContextMenu: (event: ReactMouseEvent, path: string, parentPath?: string) => void;
};

export function DesktopMiddlePane({
  appMode,
  activeSettingsSection,
  onSettingsSectionChange,
  notesPanelRef,
  middlePaneRef,
  lastLeftPaneFocusRef,
  notesTitle,
  notes,
  notePreviews,
  selectedNotes,
  onNotesKeyDown,
  onNoteClick,
  onNoteContextMenu,
}: DesktopMiddlePaneProps) {
  if (appMode === "notes") {
    return (
      <div className="pane notes-pane min-w-0">
        <div className="pane-drag-region" data-tauri-drag-region aria-hidden />
        <div
          className="pane-body focus:outline-none"
          ref={(node) => {
            notesPanelRef.current = node;
            middlePaneRef.current = node;
          }}
          tabIndex={0}
          onKeyDown={onNotesKeyDown}
          onClick={() => {
            lastLeftPaneFocusRef.current = "middle";
            focusNoScroll(middlePaneRef.current);
          }}
        >
          {notes.length === 0 && <div className="empty">No notes in {notesTitle}</div>}
          <SortableContext
            items={notes.map((n) => n.path)}
            strategy={verticalListSortingStrategy}
          >
            {notes.map((note) => (
              <NoteRow
                key={note.path}
                note={note}
                preview={notePreviews[note.path]}
                isSelected={selectedNotes.has(note.path)}
                onClick={onNoteClick}
                onContextMenu={onNoteContextMenu}
              />
            ))}
          </SortableContext>
        </div>
      </div>
    );
  }

  return (
    <SettingsMiddlePane
      activeSection={activeSettingsSection}
      onSectionChange={onSettingsSectionChange}
      middlePaneRef={middlePaneRef}
      onPaneClick={() => {
        lastLeftPaneFocusRef.current = "middle";
        focusNoScroll(middlePaneRef.current);
      }}
    />
  );
}
import { lazy, Suspense } from "react";
import { Menu } from "lucide-react";

import { NoteEditor } from "@/features/notes/editor/components/note-editor";
import { RecordingNoteHeader } from "@/features/recording/components/recording-note-header";
import { HandwritingNoteHeader } from "@/features/handwriting/components/handwriting-note-header";
import { SettingsDetailPane } from "@/features/settings/components/desktop/settings-panel";
import type { SettingsSectionId } from "@/features/settings/lib/sections";

import { focusNoScroll } from "@/shared/lib/dom";
import type { AppMode } from "@typenotes/shared/types";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/shared/ui/dropdown-menu";
import { useDesktopEditorPane } from "./hooks/use-desktop-editor-pane";

const MultiNoteLens = lazy(() =>
  import("@/features/lens/components/multi-note-lens").then((module) => ({
    default: module.MultiNoteLens,
  }))
);

type DesktopRightPaneProps = {
  appMode: AppMode;
  activeSettingsSection: SettingsSectionId;
  onOpenTrash: () => void;
};

export function DesktopRightPane({
  appMode,
  activeSettingsSection,
  onOpenTrash,
}: DesktopRightPaneProps) {
  const {
    activeNote,
    selectedNotePaths,
    activeNotePreview,
    editorMarkdown,
    handleEditorChange,
    flushSave,
    rightPaneRef,
    canOpenLens,
    shouldShowLens,
    lensNotes,
    isLensMenuOpen,
    setIsLensMenuOpen,
    openLens,
    closeLens,
    syncActiveNoteContent,
  } = useDesktopEditorPane();

  if (appMode === "notes") {
    return (
      <div className="pane editor-pane min-w-0">
        <div
          className="pane-body editor-body"
          ref={rightPaneRef}
          tabIndex={0}
          onClick={() => {
            if (shouldShowLens) {
              return;
            }
            const editorElement =
              rightPaneRef.current?.querySelector<HTMLElement>(
                ".tiptap-content[contenteditable='true']"
              ) || rightPaneRef.current;
            focusNoScroll(editorElement);
          }}
        >
          {shouldShowLens ? (
            <Suspense fallback={<div className="empty">Loading lens...</div>}>
              <MultiNoteLens
                notes={lensNotes}
                activeNote={activeNote}
                onBeforePersist={flushSave}
                onActiveNoteContentSync={syncActiveNoteContent}
                onExitLens={selectedNotePaths.length > 1 ? undefined : closeLens}
              />
            </Suspense>
          ) : (
            <div className="editor-single">
              <div className="editor-top-row">
                {canOpenLens ? (
                  <div className="editor-lens-menu-area">
                    <DropdownMenu open={isLensMenuOpen} onOpenChange={setIsLensMenuOpen}>
                      <DropdownMenuTrigger asChild>
                        <button
                          type="button"
                          className="editor-lens-menu-trigger"
                          aria-label="Open editor menu"
                        >
                          <Menu aria-hidden="true" />
                        </button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent align="end">
                        <DropdownMenuItem onClick={openLens}>
                          Open Lens
                        </DropdownMenuItem>
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </div>
                ) : null}
              </div>
              <RecordingNoteHeader notePath={activeNote} preview={activeNotePreview} />
              <HandwritingNoteHeader notePath={activeNote} preview={activeNotePreview} />
              <NoteEditor
                markdown={editorMarkdown}
                onChange={handleEditorChange}
              />
            </div>
          )}
        </div>
      </div>
    );
  }

  return (
    <SettingsDetailPane
      activeSection={activeSettingsSection}
      onOpenTrash={onOpenTrash}
      onPaneClick={() => focusNoScroll(rightPaneRef.current)}
    />
  );
}

