  padding: 0 0 10px;
  background: transparent;
}

.sidebar-folders-section {
  min-height: 0;
}

.sidebar-folders-section .nav-scroll-area {
  padding: 0 8px 10px;
}

.sidebar-folders-section .pane-body {
  padding: 0;
  background: transparent;
}

.nav-scroll-area {
  flex: 1;
  min-height: 0;
  overflow: auto;
  overscroll-behavior: contain;
}

.nav-scroll-area .pane-body {
  overflow: visible;
  min-height: 100%;
}

/* Feed/Folders tab switcher (desktop-app-shell.tsx) */

.folders-tabs {
  gap: 0;
  flex: 1;
  min-height: 0;
}

.pane-tabs-wrap {
  padding: 8px 12px 6px;
  text-transform: none;
  letter-spacing: normal;
}

.folders-tabs-list {
  border: none;
  border-radius: 0;
  background: transparent;
  padding: 0;
  height: auto;
  gap: 14px;
}

.folders-tab-trigger {
  height: auto;
  min-height: 0;
  border: none;
  background: transparent;
  color: var(--ui-muted);
  opacity: 0.66;
  font-size: 12px;
  font-weight: 600;
  line-height: 1.1;
  padding: 2px 0;
  border-radius: 0;
}

.folders-tab-trigger:hover {
