}

.folders-tab-trigger[data-state="active"] {
  color: var(--ui-text);
  opacity: 1;
  background: transparent;
  box-shadow: none;
}

.folders-tab-content {
  margin-top: 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
}

/* Row primitives (folder-row is the TreeRow container; nav-note-row is
   NavNoteRow). The shared `.item-row`/`.item-row.selected` base and its drag
   ghost live in app.css since note-row.tsx and settings-panel.tsx reuse them
   too — everything below only ever applies to tree rows. */

.folder-row {
  cursor: default;
}

.item-row.drop-before::before,
.item-row.drop-after::after {
  content: "";
  position: absolute;
  left: 8px;
  right: 8px;
  height: 2px;
  background: #8aa0b5;
}

.item-row.drop-before::before {
  top: 0;
}

.item-row.drop-after::after {
  bottom: 0;
}

.item-row.drop-inside {
  background: #f4f7fa;
  outline: 1px dashed #9cb1c5;
}

.tree-root {
  min-height: 100%;
}

.tree-root.drop-inside {
  outline: 1px dashed #9aaec1;
  outline-offset: -6px;
}

.tree-children {
  margin-left: 0;
}

.folder-row.is-dragging {
  opacity: 0.4;
}

.drag-ghost {
  max-width: 180px;
  padding: 4px 8px;
  background: rgba(255, 255, 255, 0.86);
  border: 1px solid var(--ui-border);
  border-radius: 0;
  font-size: 11px;
  font-weight: 500;
  color: var(--ui-text);
  box-shadow: none;
  transform: scale(1);
  transform-origin: center;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  pointer-events: none;
}

.item-label {
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.icon-btn {
  border: none;
  background: none;
  padding: 2px 6px;
  font-size: 12px;
  color: var(--ui-muted);
  cursor: pointer;
  border-radius: 0;
}

.icon-btn:hover {
  color: var(--ui-text);
  background: #f3f5f7;
}

.rename-input {
  flex: 1;
  border: 1px solid var(--ui-border-strong);
  background: rgba(255, 255, 255, 0.74);
  border-radius: 0;
  padding: 4px 8px;
  font-size: 13px;
  font-family: inherit;
  color: var(--ui-text);
}

.rename-input:focus {
  outline: none;
  border-color: #95a9bb;
  box-shadow: none;
}

