  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 2px 12px 8px;
  color: var(--ui-muted);
  font-size: 11px;
  font-weight: 600;
}

.feed-filter-select {
  width: 112px;
  height: 26px;
  border-color: var(--ui-border);
  background: color-mix(in srgb, var(--ui-pane) 86%, transparent);
  padding-left: 8px;
  font-size: 11px;
  box-shadow: none;
}

