// Feed navigation renders synthetic time buckets, not the folder tree.
import type { MouseEvent as ReactMouseEvent, RefObject } from "react";
import { useCallback } from "react";
import { useShallow } from "zustand/react/shallow";

import { useEditor } from "@/features/notes/editor/hooks/editor-context";
import { useNotesTree } from "@/features/notes/navigation/state/notes-tree-context";
import { type DesktopContextMenuState } from "@/app/hooks/use-tree-interactions";
import { useSelection } from "@/app/state/selection-store";
import { FEED_FOLDER_PATH } from "@typenotes/shared/constants";
import { focusNoScroll } from "@/shared/lib/dom";
import { computeRangeSelection } from "@/shared/lib/selection";
import { NativeSelect, NativeSelectOption } from "@/shared/ui/native-select";
import type { FeedNoteFilter } from "../model/feed-tree-model";
import { TreeNode } from "./tree-node";

type FeedPanelProps = {
  paneBodyRef: RefObject<HTMLDivElement | null>;
  onNavigateToNotes?: () => void;
  onPaneClick?: () => void;
  onPaneKeyDown?: (event: React.KeyboardEvent<HTMLDivElement>) => void;
  onOpenContextMenu: (state: DesktopContextMenuState) => void;
};

export function FeedPanel({
  paneBodyRef,
  onNavigateToNotes,
  onPaneClick,
  onPaneKeyDown,
  onOpenContextMenu,
}: FeedPanelProps) {
  const { clearDraft, clearNote } = useEditor();
  const {
    feedTreeData,
    feedNodeById,
    feedNoteFilter,
    setFeedNoteFilter,
    activeFeedGroup,
    setActiveFeedGroup,
    expanded,
    setExpanded,
    allNotePreviews,
    feedLoading,
    shouldNestNotesInNavigation,
  } = useNotesTree();
  const {
    selectFolder,
    selectNote,
    setSelectedFolders,
    setLastSelectedFolder,
    setActiveFolder,
    selectedNotes,
    setSelectedNotes,
    lastSelectedNote,
    setLastSelectedNote,
    setActiveNote,
  } = useSelection(
    useShallow((state) => ({
      selectFolder: state.selectFolder,
      selectNote: state.selectNote,
      setSelectedFolders: state.setSelectedFolders,
      setLastSelectedFolder: state.setLastSelectedFolder,
      setActiveFolder: state.setActiveFolder,
      selectedNotes: state.selectedNotes,
      setSelectedNotes: state.setSelectedNotes,
      lastSelectedNote: state.lastSelectedNote,
      setLastSelectedNote: state.setLastSelectedNote,
      setActiveNote: state.setActiveNote,
    }))
  );

  const selectFeedGroup = useCallback(
    (groupId: string) => {
      onNavigateToNotes?.();
      setActiveFeedGroup(groupId);
      selectFolder(FEED_FOLDER_PATH);
      clearDraft();
      clearNote();
      focusNoScroll(paneBodyRef.current);
    },
    [
      clearDraft,
      clearNote,
      onNavigateToNotes,
      paneBodyRef,
      selectFolder,
      setActiveFeedGroup,
    ]
  );

  const handleNoteSelect = useCallback(
    (notePath: string, event: ReactMouseEvent, parentPath: string) => {
      onNavigateToNotes?.();
      const parentNode = feedNodeById.get(parentPath);
      const notePaths = parentNode?.notes.map((note) => note.path) || [];
      selectNote(
        notePath,
        FEED_FOLDER_PATH,
        computeRangeSelection(event, selectedNotes, notePaths, lastSelectedNote, notePath)
      );
      setActiveFeedGroup(parentPath);
      if (shouldNestNotesInNavigation) {
        focusNoScroll(paneBodyRef.current);
      }
    },
    [
      feedNodeById,
      lastSelectedNote,
      onNavigateToNotes,
      paneBodyRef,
      selectNote,
      selectedNotes,
      setActiveFeedGroup,
      shouldNestNotesInNavigation,
    ]
  );

  const handleToggle = useCallback(
    (event: ReactMouseEvent, id: string) => {
      event.stopPropagation();
      setExpanded((prev) => {
        const next = new Set(prev);
        if (next.has(id)) {
          next.delete(id);
        } else {
          next.add(id);
        }
        return next;
      });
    },
    [setExpanded]
  );

  const handleNoteContextMenu = useCallback(
    (event: ReactMouseEvent, notePath: string, parentPath: string) => {
      event.preventDefault();
      event.stopPropagation();
      const parentNode = feedNodeById.get(parentPath);
      const notePaths = parentNode?.notes.map((note) => note.path) || [];
      const targetPaths =
        selectedNotes.size > 1 && selectedNotes.has(notePath) ? Array.from(selectedNotes) : [notePath];
      setSelectedFolders(new Set([FEED_FOLDER_PATH]));
      setLastSelectedFolder(FEED_FOLDER_PATH);
      setActiveFolder(FEED_FOLDER_PATH);
      if (!selectedNotes.has(notePath)) {
        setSelectedNotes(new Set([notePath]));
        setLastSelectedNote(notePath);
      }
      setActiveFeedGroup(parentPath);
      setActiveNote(notePath);
      focusNoScroll(paneBodyRef.current);
      onOpenContextMenu({
        kind: "note",
        x: event.clientX,
        y: event.clientY,
        path: notePath,
        parentPath,
        targetPaths: targetPaths.length > 0 ? targetPaths : notePaths,
      });
    },
    [
      feedNodeById,
      onOpenContextMenu,
      paneBodyRef,
      selectedNotes,
      setActiveFeedGroup,
      setActiveFolder,
      setActiveNote,
      setLastSelectedFolder,
      setLastSelectedNote,
      setSelectedFolders,
      setSelectedNotes,
    ]
  );

  return (
    <div className="feed-panel-layout">
      <div className="feed-filter-bar">
        <label htmlFor="feed-note-filter">Show</label>
        <NativeSelect
          id="feed-note-filter"
          size="sm"
          value={feedNoteFilter}
          onChange={(event) =>
            setFeedNoteFilter(event.target.value as FeedNoteFilter)
          }
          aria-label="Filter Feed notes"
          className="feed-filter-select"
        >
          <NativeSelectOption value="all">All notes</NativeSelectOption>
          <NativeSelectOption value="active">Active</NativeSelectOption>
          <NativeSelectOption value="reviewed">Reviewed</NativeSelectOption>
          <NativeSelectOption value="unreviewed">Unreviewed</NativeSelectOption>
          <NativeSelectOption value="archived">Archived</NativeSelectOption>
        </NativeSelect>
      </div>
      <div
        className="nav-scroll-area focus:outline-none"
        ref={paneBodyRef}
        tabIndex={0}
        onKeyDown={onPaneKeyDown}
        onClick={(event) => {
          if (onPaneClick) {
            onPaneClick();
          }
          if (event.target === event.currentTarget && feedTreeData[0]) {
            selectFeedGroup(activeFeedGroup || feedTreeData[0].id);
          }
        }}
      >
        {feedTreeData.length === 0 ? (
          <div className="empty">
            {feedLoading
              ? "Loading feed..."
              : feedNoteFilter === "all"
                ? "No feed notes yet."
                : `No ${feedNoteFilter} notes.`}
          </div>
        ) : (
          <div className="pane-body tree-root feed-navigation-tree">
            {feedTreeData.map((node) => (
              <TreeNode
                key={node.id}
                node={node}
                depth={0}
                selectedIds={
                  activeFeedGroup ? new Set([activeFeedGroup]) : new Set()
                }
                selectedNoteIds={selectedNotes}
                showNotesAsChildren={shouldNestNotesInNavigation}
// Provider hub for the notes navigation slice.
import {
  createContext,
  useContext,
  useEffect,
  type Dispatch,
  type ReactNode,
  type SetStateAction,
} from "react";
import { listen } from "@tauri-apps/api/event";

import { useSelection } from "@/app/state/selection-store";
import type { FolderNode, NoteEntry, VisibleNavigationItem } from "@typenotes/shared/types";
import type { NotePreview } from "@typenotes/shared/format";
import type { TreeItem, FlattenedItem } from "@/features/notes/navigation/model/types";
import type {
  FeedNoteFilter,
  FeedTreeNode,
} from "@/features/notes/navigation/model/feed-tree-model";
import { useNotesTreeState } from "./use-notes-tree-state";
import { useNotesTreeActions } from "./use-notes-tree-actions";

type NotesTreeContextValue = {
  tree: FolderNode | null;
  treeData: TreeItem[];
  flatItems: FlattenedItem[];
  visibleItems: FlattenedItem[];
  orderedIds: string[];
  flatItemById: Map<string, FlattenedItem>;
  expanded: Set<string>;
  setExpanded: Dispatch<SetStateAction<Set<string>>>;
  notes: NoteEntry[];
  allNotes: NoteEntry[];
  notePreviews: Record<string, NotePreview>;
  allNotePreviews: Record<string, NotePreview>;
  activeNode: FolderNode | null;
  visibleNavigationItems: VisibleNavigationItem[];
  feedVisibleNavigationItems: VisibleNavigationItem[];
  feedTreeData: FeedTreeNode[];
  feedNodeById: Map<string, FeedTreeNode>;
  feedNoteFilter: FeedNoteFilter;
  setFeedNoteFilter: Dispatch<SetStateAction<FeedNoteFilter>>;
  activeFeedGroup: string;
  setActiveFeedGroup: Dispatch<SetStateAction<string>>;
  activeFeedNode: FeedTreeNode | null;
  feedNotes: Array<NoteEntry & { timestampMs: number }>;
  feedNotePreviews: Record<string, NotePreview>;
  feedLoading: boolean;
  parentById: Record<string, string | null>;
  renamingFolder: string | null;
  renameValue: string;
  setRenameValue: (value: string) => void;
  startRenameFolder: (path: string) => void;
  submitRenameFolder: () => Promise<void>;
  cancelRenameFolder: () => void;
  refreshTree: () => Promise<void>;
  createNewNote: (
    preferredFolderPath?: string,
    initialContent?: string,
    targetTimestampMs?: number
  ) => Promise<string | null>;
  deleteNotes: (paths: string[]) => Promise<boolean>;
  deleteFolders: (paths: string[]) => Promise<void>;
  moveNotesToArchive: (paths: string[]) => Promise<void>;
  moveNotesToFolder: (paths: string[], destinationPath: string) => Promise<void>;
  updateNoteMarkers: (
    paths: string[],
    markers: { archived?: boolean | null; reviewed?: boolean | null }
  ) => Promise<void>;
  flattenIntoFeed: (folderPaths: string[], notePaths: string[]) => Promise<void>;
  showNoteInfo: (path: string) => Promise<void>;
  shouldNestNotesInNavigation: boolean;
  setTree: Dispatch<SetStateAction<FolderNode | null>>;
};

const NotesTreeContext = createContext<NotesTreeContextValue | null>(null);

export function NotesTreeProvider({ children }: { children: ReactNode }) {
  const activeFolder = useSelection((state) => state.activeFolder);
  const state = useNotesTreeState({ activeFolder });
  const actions = useNotesTreeActions({
    tree: state.tree,
    refreshTree: state.refreshTree,
    renamingFolder: state.renamingFolder,
    setRenamingFolder: state.setRenamingFolder,
    renameValue: state.renameValue,
    setRenameValue: state.setRenameValue,
  });

  // A phone pushing over local sync changes the notes on disk behind the
  // frontend's back; the backend emits this event after each accepted push.
  const { refreshTree } = state;
  useEffect(() => {
    const unlisten = listen("local-sync-push-received", () => {
      console.log("[notes] local sync push received — refreshing tree");
      void refreshTree();
    });
    return () => {
      void unlisten.then((dispose) => dispose());
    };
  }, [refreshTree]);

  return (
    <NotesTreeContext.Provider value={{ ...state, ...actions }}>
      {children}
    </NotesTreeContext.Provider>
  );
}

